import {ROOTS,SCALES,STYLES,MOODS,RHYTHM_GRIDS} from './engine/music-data.js';
import {HarmonyEngine} from './engine/harmony.js';import {RhythmEngine} from './engine/rhythm.js';import {MidiWriter,validateMidi} from './engine/midi.js';import {progressionExplanation} from './engine/analyzer.js';import {midiName} from './engine/theory.js';
const $=id=>document.getElementById(id);const harmony=new HarmonyEngine(),rhythm=new RhythmEngine(),midi=new MidiWriter();
const state={progression:[],events:[],history:[],future:[],audio:null,playing:[],favorites:JSON.parse(localStorage.getItem('chordbloom:favorites')||'[]')};
const opts={key:ROOTS,scale:Object.keys(SCALES),style:Object.keys(STYLES),mood:Object.keys(MOODS),length:[2,3,4,5,6,7,8,12,16],generationMode:['CHORDS','RHYTHMIC CHORDS','ARPEGGIO','BROKEN CHORDS','STRUM','PULSE'],cadence:['Auto','Strong Resolution','Soft Resolution','Loop Friendly','No Resolution','Suspended'],tensionCurve:['Flat','Calm → Build','Build → Peak → Resolve','Wave','Slow Burn','Immediate Tension','Long Resolution'],topVoice:['Free','Smooth','Ascending','Descending','Pedal','Stepwise','Melodic'],bassMovement:['Auto','Root','Smooth','Stepwise','Fifth-heavy','Pedal','Walking','Descending','Ascending'],grid:Object.keys(RHYTHM_GRIDS),rhythmPattern:['Straight','Offbeat','Syncopated','3-3-2 / Tresillo','Euclidean 3/8','Euclidean 5/8','Sparse','Dense','House Stabs','Garage','Broken Beat','Ambient','Random On-Grid'],articulation:['Legato','Normal','Tenuto','Staccato','Short','Varied On-Grid'],harmonicRhythm:['Fixed','Varied On-Grid','Slow → Fast','Fast → Slow','Tension Driven','Syncopated'],arpPattern:['Up','Down','Up/Down','Down/Up','Random','Outside → In','Inside → Out','Alternate','Converge','Diverge'],arpOctaves:[1,2,3,4],strumMode:['Up','Down','Alternating','Random','Humanized'],velocityMode:['Fixed Velocity','Dynamic','Accent Pattern','Randomized within range']};
for(const [id,values] of Object.entries(opts)){const el=$(id);for(const v of values){const o=document.createElement('option');o.value=o.textContent=v;el.appendChild(o)}}
Object.assign($('key'),{value:'A'});$('scale').value='Dorian';$('style').value='UK GARAGE / UKG';$('mood').value='Dreamy';$('length').value='4';$('generationMode').value='CHORDS';$('cadence').value='Loop Friendly';$('tensionCurve').value='Build → Peak → Resolve';$('topVoice').value='Smooth';$('bassMovement').value='Auto';$('grid').value='1/16';$('rhythmPattern').value='Garage';$('articulation').value='Normal';$('harmonicRhythm').value='Fixed';$('arpPattern').value='Up/Down';$('arpOctaves').value='2';$('strumMode').value='Up';$('velocityMode').value='Dynamic';
const sliderIds=['complexity','tension','adventurous','spread','voiceLeading','swing','strumWidth'];for(const id of sliderIds){$(id).addEventListener('input',()=>$(id+'Out').value=$(id).value)}
function settings(){return {key:$('key').value,scale:$('scale').value,style:$('style').value,mood:$('mood').value,length:+$('length').value,bpm:+$('bpm').value,seed:+$('seed').value,generationMode:$('generationMode').value,cadence:$('cadence').value,complexity:+$('complexity').value,tension:+$('tension').value,adventurous:+$('adventurous').value,spread:+$('spread').value,voiceLeading:+$('voiceLeading').value,tensionCurve:$('tensionCurve').value,loopFriendly:$('loopFriendly').checked,topVoice:$('topVoice').value,bassMovement:$('bassMovement').value,grid:$('grid').value,rhythmPattern:$('rhythmPattern').value,articulation:$('articulation').value,swing:+$('swing').value,harmonicRhythm:$('harmonicRhythm').value,minNoteLength:+$('minNoteLength').value,maxNoteLength:+$('maxNoteLength').value,arpPattern:$('arpPattern').value,arpOctaves:+$('arpOctaves').value,strumMode:$('strumMode').value,strumWidth:+$('strumWidth').value,velocityMode:$('velocityMode').value,minVelocity:+$('minVelocity').value,maxVelocity:+$('maxVelocity').value,multiTrack:$('multiTrack').checked,showTheory:$('showTheory').checked,chordGridUnits:8};}
function pushHistory(){if(state.progression.length)state.history.push(structuredClone(state.progression));if(state.history.length>40)state.history.shift();state.future=[]}
function generate(){try{pushHistory();state.progression=harmony.generate(settings(),state.progression);refresh('Generated')}catch(e){fail(e)}}
function refresh(label='Updated'){try{state.events=rhythm.render(state.progression,settings());renderChords();renderRoll();$('why').textContent=progressionExplanation(state.progression,settings());$('theoryPanel').hidden=!settings().showTheory;$('progressionTitle').textContent=state.progression.map(c=>c.symbol+(c.inversion?`/${midiName(c.voicing[0],settings().key).replace(/-?\d+$/,'')}`:'')).join(' → ')||'Generate a progression';$('eventCount').textContent=`${state.events.length} notes`;$('status').className='status';$('status').textContent=label;}catch(e){fail(e)}}
function renderChords(){const host=$('chords');host.innerHTML='';state.progression.forEach((c,i)=>{const card=document.createElement('article');card.className='chord-card'+(c.locked?' locked':'');card.innerHTML=`<div class="chord-number">CHORD ${i+1}</div><div class="chord-symbol">${esc(c.symbol)}</div><div class="roman">${esc(c.roman)}</div><div class="function">${esc(c.function)}</div><div class="pitches">${c.pitches.map(esc).join(' · ')}</div><div class="meta"><span>Bass ${esc(c.bassName)}</span><span>Inv. ${c.inversion}</span><span>${esc(c.source)}</span><span>Tension ${Math.round(c.tension)}</span></div><div class="explain">${esc(c.explanation)}</div><div class="card-actions"><button data-lock="${i}" class="${c.locked?'active':''}">${c.locked?'LOCKED':'LOCK'}</button><button data-alt="${i}">ALTERNATIVE</button><button data-aud="${i}">AUDITION</button></div>`;host.appendChild(card)});host.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>{const i=+b.dataset.lock;state.progression[i].locked=!state.progression[i].locked;refresh(state.progression[i].locked?'Chord locked':'Chord unlocked')});host.querySelectorAll('[data-alt]').forEach(b=>b.onclick=()=>{pushHistory();state.progression=harmony.alternative(+b.dataset.alt,settings(),state.progression);refresh('Alternative generated')});host.querySelectorAll('[data-aud]').forEach(b=>b.onclick=()=>auditionChord(+b.dataset.aud));}
function renderRoll(){const cv=$('pianoRoll'),ctx=cv.getContext('2d'),w=cv.width,h=cv.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#090b10';ctx.fillRect(0,0,w,h);if(!state.events.length)return;const min=Math.max(0,Math.min(...state.events.map(e=>e.note))-3),max=Math.min(127,Math.max(...state.events.map(e=>e.note))+3),end=Math.max(...state.events.map(e=>e.start+e.duration));ctx.strokeStyle='#1d222d';ctx.lineWidth=1;for(let n=min;n<=max;n++){const y=h-(n-min+1)/(max-min+2)*h;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}for(let t=0;t<=end;t+=480){const x=t/end*w;ctx.strokeStyle=t%(480*4)===0?'#384050':'#202530';ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(const e of state.events){const x=e.start/end*w,ww=Math.max(2,e.duration/end*w),y=h-(e.note-min+1)/(max-min+2)*h-5;ctx.fillStyle=e.track==='Arpeggio'?'#6de8ff':'#b8ff5a';ctx.globalAlpha=.78;ctx.fillRect(x,y,ww,8)}ctx.globalAlpha=1}
function downloadMidi(){try{if(!state.events.length)throw new Error('Generate a progression first.');const s=settings(),bytes=midi.write(state.events,{bpm:s.bpm,trackName:'ChordBloom',multiTrack:s.multiTrack});if(!validateMidi(bytes))throw new Error('MIDI validation failed.');const blob=new Blob([bytes],{type:'audio/midi'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ChordBloom_${s.key}${slug(s.scale)}_${slug(s.style)}_${s.seed}.mid`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('MIDI exported')}catch(e){fail(e)}}
function audioContext(){if(!window.AudioContext&&!window.webkitAudioContext)throw new Error('WebAudio is unavailable in this browser.');if(!state.audio)state.audio=new (window.AudioContext||window.webkitAudioContext)();return state.audio}
function stop(){for(const x of state.playing){try{x.stop()}catch{}}state.playing=[];$('status').textContent='Stopped'}
function play(){try{stop();const ac=audioContext(),s=settings(),secPerTick=60/s.bpm/480,now=ac.currentTime+.04;for(const e of state.events){const osc=ac.createOscillator(),gain=ac.createGain();osc.type='triangle';osc.frequency.value=440*Math.pow(2,(e.note-69)/12);gain.gain.setValueAtTime(0,now+e.start*secPerTick);gain.gain.linearRampToValueAtTime(.045*(e.velocity/127),now+e.start*secPerTick+.012);gain.gain.setValueAtTime(.035*(e.velocity/127),now+(e.start+Math.max(1,e.duration-15))*secPerTick);gain.gain.linearRampToValueAtTime(0,now+(e.start+e.duration)*secPerTick);osc.connect(gain).connect(ac.destination);osc.start(now+e.start*secPerTick);osc.stop(now+(e.start+e.duration)*secPerTick+.03);state.playing.push(osc)}$('status').textContent='Playing'}catch(e){fail(e)}}
function auditionChord(i){try{stop();const ac=audioContext(),now=ac.currentTime+.02;for(const n of state.progression[i].voicing){const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=440*Math.pow(2,(n-69)/12);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.055,now+.02);g.gain.exponentialRampToValueAtTime(.0001,now+1.2);o.connect(g).connect(ac.destination);o.start(now);o.stop(now+1.25);state.playing.push(o)}}catch(e){fail(e)}}
function save(){if(!state.progression.length)return toast('Nothing to save');const s=settings(),name=prompt('Progression name',state.progression.map(c=>c.symbol).join(' – '));if(!name)return;state.favorites.unshift({id:Date.now(),name,settings:s,progression:structuredClone(state.progression)});persistFavs();renderFavorites();toast('Saved locally')}
function persistFavs(){localStorage.setItem('chordbloom:favorites',JSON.stringify(state.favorites))}function renderFavorites(){const h=$('favorites');h.innerHTML=state.favorites.length?'':'<span class="tagline">Nothing saved yet.</span>';for(const f of state.favorites){const d=document.createElement('div');d.className='favorite-item';d.innerHTML=`<div><strong>${esc(f.name)}</strong><div class="muted">${f.progression.map(c=>esc(c.symbol)).join(' → ')}</div></div><div><button data-load="${f.id}">LOAD</button> <button data-del="${f.id}">DELETE</button></div>`;h.appendChild(d)}h.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>{const f=state.favorites.find(x=>x.id===+b.dataset.load);pushHistory();state.progression=structuredClone(f.progression);$('seed').value=f.settings.seed;refresh('Loaded')});h.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{state.favorites=state.favorites.filter(x=>x.id!==+b.dataset.del);persistFavs();renderFavorites()})}
function undo(){if(!state.history.length)return;state.future.push(structuredClone(state.progression));state.progression=state.history.pop();refresh('Undo')}function redo(){if(!state.future.length)return;state.history.push(structuredClone(state.progression));state.progression=state.future.pop();refresh('Redo')}
function makeIt(kind){const map={DARKER:['tension',12],BRIGHTER:['adventurous',-8],SEXIER:['complexity',14],DREAMIER:['spread',14],SIMPLER:['complexity',-18],RICHER:['complexity',18],'MORE EMOTIONAL':['tension',10],'MORE CLUB':['spread',-10],'MORE JAZZY':['adventurous',14],WEIRDER:['adventurous',18],'MORE DIATONIC':['adventurous',-20],'MORE SUSPENDED':['tension',5],'MORE TENSE':['tension',18],'MORE RESOLVED':['tension',-14]};const [id,d]=map[kind];$(id).value=Math.max(0,Math.min(100,+$(id).value+d));if($(id+'Out'))$(id+'Out').value=$(id).value;pushHistory();state.progression=harmony.moreLikeThis(settings(),state.progression);refresh(kind.toLowerCase())}
for(const k of ['DARKER','BRIGHTER','SEXIER','DREAMIER','SIMPLER','RICHER','MORE EMOTIONAL','MORE CLUB','MORE JAZZY','WEIRDER','MORE DIATONIC','MORE SUSPENDED','MORE TENSE','MORE RESOLVED']){const b=document.createElement('button');b.textContent=k;b.onclick=()=>makeIt(k);$('makeIt').appendChild(b)}
$('generate').onclick=generate;$('moreLike').onclick=()=>{if(!state.progression.length)return generate();pushHistory();state.progression=harmony.moreLikeThis(settings(),state.progression);refresh('Variation generated')};$('play').onclick=play;$('stop').onclick=stop;$('download').onclick=downloadMidi;$('newSeed').onclick=()=>{$('seed').value=Math.floor(Math.random()*999999999)+1;generate()};$('save').onclick=save;$('undo').onclick=undo;$('redo').onclick=redo;$('reset').onclick=()=>{localStorage.removeItem('chordbloom:settings');location.reload()};$('showTheory').onchange=()=>refresh();for(const id of ['generationMode','grid','rhythmPattern','articulation','swing','harmonicRhythm','minNoteLength','maxNoteLength','arpPattern','arpOctaves','strumMode','strumWidth','velocityMode','minVelocity','maxVelocity'])$(id).addEventListener('change',()=>state.progression.length&&refresh('Pattern updated'));
function esc(x){return String(x??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function slug(x){return String(x).replace(/[^A-Za-z0-9]+/g,'')}function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}function fail(e){console.error(e);$('status').textContent=e.message||String(e);$('status').className='status error';toast(e.message||'Error')}
renderFavorites();generate();
